-- >>> NATIVE_BASELINE_PART 0129 | supabase/sql/120_admin_console_fixes.sql | 120_admin_console_fixes.sql <<<
-- 120_admin_console_fixes.sql
-- 관리자 기능 점검(2026-07-17) 후속 수정 모음. 전 구간 멱등(재실행 안전).
--
-- A. content_reports 상태 CHECK 확장
--    검수 콘솔의 숨김/삭제 처리(updateContentReportModerationAction)가
--    status='hidden'/'removed' 를 쓰지만 032 CHECK가 거부 → 콘텐츠만 변경되고
--    신고 상태 갱신이 실패하는 불일치. 허용값에 두 상태를 추가한다.
-- B. disputes 상태 CHECK 확장
--    제재 액션(applyDisputeSanctionAction)의 on_hold/sanction_* 상태를 허용.
--    기존 CHECK 위반으로 제재 전체(계정 정지 연동 포함)가 첫 UPDATE에서 실패했다.
-- C. 실 DB에만 수동 적용돼 있던 관리자 정책 백포트 (레포 SQL로 재구축 시에도 관리자 콘솔이 동작하도록)
--    - users_admin_select_all / mp_admin_select_all / student_id_images_admin_select
-- D. 게시판 v2 comments 정리
--    - 조건 `true` 인 레거시 공개 정책 3종 제거(삭제된 댓글까지 전체 공개되던 누출).
--      정상 노출은 comments_select_visible(is_deleted=false, anon+authenticated)이 계속 담당.
--    - 관리자 검수용 select(숨김 포함)/update/delete 정책 추가.
-- E. 관리자 증거 열람 보강
--    - question-room-attachments / scan-annotations 버킷과 scan_annotations 테이블에
--      관리자 SELECT 정책 추가(분쟁·신고 검토 시 첨부 확인용, service_role 불필요).

-- ── A. content_reports 상태 CHECK ────────────────────────────────────────────
alter table public.content_reports
  drop constraint if exists content_reports_status_allowed;
alter table public.content_reports
  add constraint content_reports_status_allowed
  check (status = any (array[
    'pending', 'reviewing', 'resolved', 'rejected', 'dismissed',
    'hidden', 'removed'
  ]));

-- ── B. disputes 상태 CHECK ──────────────────────────────────────────────────
alter table public.disputes
  drop constraint if exists disputes_status_check;
alter table public.disputes
  add constraint disputes_status_check
  check (status = any (array[
    'open', 'under_review', 'resolved', 'dismissed', 'escalated',
    'on_hold', 'sanction_7d', 'sanction_30d', 'sanction_permanent'
  ]));

-- ── C. 관리자 정책 백포트 ────────────────────────────────────────────────────
drop policy if exists users_admin_select_all on public.users;
create policy users_admin_select_all on public.users
  for select to authenticated
  using ((select public.is_admin()) = true);

drop policy if exists mp_admin_select_all on public.mentor_profiles;
create policy mp_admin_select_all on public.mentor_profiles
  for select to authenticated
  using ((select public.is_admin()) = true);

drop policy if exists student_id_images_admin_select on storage.objects;
create policy student_id_images_admin_select on storage.objects
  for select to authenticated
  using (bucket_id = 'student-id-images' and (select public.is_admin()) = true);

-- ── D. comments(게시판 v2) 정책 정리 ─────────────────────────────────────────
drop policy if exists "누구나 댓글 읽기" on public.comments;
drop policy if exists "로그인 유저 댓글 작성" on public.comments;
drop policy if exists "본인 댓글 삭제" on public.comments;

drop policy if exists comments_admin_select_all on public.comments;
create policy comments_admin_select_all on public.comments
  for select to authenticated
  using ((select public.is_admin()) = true);

drop policy if exists comments_admin_update on public.comments;
create policy comments_admin_update on public.comments
  for update to authenticated
  using ((select public.is_admin()) = true)
  with check ((select public.is_admin()) = true);

drop policy if exists comments_admin_delete on public.comments;
create policy comments_admin_delete on public.comments
  for delete to authenticated
  using ((select public.is_admin()) = true);

-- ── E. 관리자 증거 열람(스토리지·주석 테이블) ────────────────────────────────
drop policy if exists qra_storage_read_admin on storage.objects;
create policy qra_storage_read_admin on storage.objects
  for select to authenticated
  using (bucket_id = 'question-room-attachments' and (select public.is_admin()) = true);

drop policy if exists scan_annotations_obj_admin_select on storage.objects;
create policy scan_annotations_obj_admin_select on storage.objects
  for select to authenticated
  using (bucket_id = 'scan-annotations' and (select public.is_admin()) = true);

drop policy if exists scan_annotations_admin_select on public.scan_annotations;
create policy scan_annotations_admin_select on public.scan_annotations
  for select to authenticated
  using ((select public.is_admin()) = true);

comment on constraint content_reports_status_allowed on public.content_reports is
  '120: hidden/removed 추가 — 검수 콘솔 숨김/삭제 처리와 정합.';
comment on constraint disputes_status_check on public.disputes is
  '120: on_hold/sanction_7d/sanction_30d/sanction_permanent 추가 — 분쟁 제재 액션과 정합.';

-- >>> NATIVE_BASELINE_PART 0130 | supabase/sql/122_signup_role_no_admin.sql | 122_signup_role_no_admin.sql <<<
-- --------------------------------------------------------------------------
-- 122_signup_role_no_admin.sql
-- 목적(P0-1): 가입 메타데이터(app_role)로 admin 권한 자가 획득 차단.
--   handle_new_auth_user() 의 role 화이트리스트에서 'admin' 을 제거한다.
--   001_initial_auth_profile.sql 본문과 완전히 동일하며, 단 한 줄
--   (role 분기 화이트리스트)만 'admin' 미허용으로 교정한다.
-- 선행: 001_initial_auth_profile.sql
-- 참고: 운영/스테이징 DB에는 동등 교정이 이미 적용되어 있음
--   (supabase_migrations 원장: 20260717044250 fix_xv01_signup_admin_provisioning).
--   본 파일은 저장소 클린 설치 정본(001)과의 정합용 — 클린 설치 시에도
--   가입 경로로 admin 승격이 불가능하도록 닫는다. (서버 방어는 DB가 정본;
--   UI/TS 메타 정규화는 보조일 뿐이다.)
-- --------------------------------------------------------------------------

create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  m jsonb;
  r text;
  subj text[];
  subj_str text;
  bdate date;
begin
  m := coalesce(NEW.raw_user_meta_data, '{}'::jsonb);
  r := lower(trim(m->>'app_role'));
  if r is null or r = '' then
    r := 'student';
  end if;
  -- P0-1: 'admin' 제거 — 가입 메타로는 student/mentor 만 허용, 그 외 전부 student.
  if r not in ('student', 'mentor') then
    r := 'student';
  end if;

  subj_str := nullif(trim(m->>'teaching_subjects_csv'), '');
  if subj_str is not null then
    subj := array(
      select trim(both ' ' from x)
      from unnest(string_to_array(subj_str, ',')) as x
      where length(trim(both ' ' from x)) > 0
    );
  else
    subj := '{}';
  end if;

  begin
    bdate := (m->>'birth_date')::date;
  exception when others then
    bdate := null;
  end;

  insert into public.users (
    id, role, status, full_name, nickname, email,
    grade_level, student_status, birth_date,
    terms_agreed_at, privacy_agreed_at, marketing_agreed, updated_at
  ) values (
    NEW.id, r, 'active',
    nullif(trim(m->>'full_name'), ''),
    nullif(trim(m->>'nickname'), ''),
    coalesce(NEW.email, ''),
    nullif(trim(m->>'grade_level'), ''),
    nullif(trim(m->>'student_status'), ''),
    bdate,
    case when (m->>'terms_agreed') = 'true' then now() else null end,
    case when (m->>'privacy_agreed') = 'true' then now() else null end,
    case when (m->>'marketing_agreed') = 'true' then true else false end,
    now()
  )
  on conflict (id) do update set
    role = excluded.role,
    full_name = coalesce(excluded.full_name, public.users.full_name),
    nickname = coalesce(excluded.nickname, public.users.nickname),
    email = excluded.email,
    grade_level = coalesce(excluded.grade_level, public.users.grade_level),
    student_status = coalesce(excluded.student_status, public.users.student_status),
    birth_date = coalesce(excluded.birth_date, public.users.birth_date),
    terms_agreed_at = coalesce(excluded.terms_agreed_at, public.users.terms_agreed_at),
    privacy_agreed_at = coalesce(excluded.privacy_agreed_at, public.users.privacy_agreed_at),
    marketing_agreed = excluded.marketing_agreed,
    updated_at = now();

  if r = 'mentor' then
    insert into public.mentor_profiles (
      user_id, university_name, department_name, teaching_subjects, high_school_name, intro_line,
      verification_status, student_id_image_url, updated_at
    ) values (
      NEW.id,
      coalesce(nullif(trim(m->>'university_name'), ''), '(미입력)'),
      coalesce(nullif(trim(m->>'department_name'), ''), '(미입력)'),
      coalesce(subj, '{}'),
      coalesce(nullif(trim(m->>'high_school_name'), ''), '(미입력)'),
      nullif(trim(m->>'intro_line'), ''),
      'pending',
      null,
      now()
    )
    on conflict (user_id) do update set
      university_name = excluded.university_name,
      department_name = excluded.department_name,
      teaching_subjects = excluded.teaching_subjects,
      high_school_name = excluded.high_school_name,
      intro_line = coalesce(excluded.intro_line, public.mentor_profiles.intro_line),
      updated_at = now();

    insert into public.verification_logs (user_id, log_type, status, memo) values
      (NEW.id, 'mentor_verification', 'pending', 'sign-up');
  end if;

  return NEW;
end;
$$;

-- >>> NATIVE_BASELINE_PART 0131 | supabase/sql/123_reviews_converge.sql | 123_reviews_converge.sql <<<
-- --------------------------------------------------------------------------
-- 123_reviews_converge.sql   (P0-2 · 리뷰 스키마/데이터 수렴 — 멱등, 단일 트랜잭션)
-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과.
--   ⚠️ execute_sql 로 적용해 supabase_migrations 원장에는 미기재(드리프트) — 원장 기재는 별도 승인 후.]
-- 목적: 하이브리드(042형 student_id/content NOT NULL + 004형 author_id/body) 상태를
--   정본(author_id/body, subscription_count nullable, unique(mentor_id,author_id))으로 수렴.
--   현재 웹 write(author_id/body만 INSERT)가 레거시 NOT NULL(student_id/content) 위반으로
--   실패하는 결함을 해소한다.
-- 선행: 004(reviews base)·042(reviews core). 정책 정본화는 126_reviews_rls_hardening.sql.
-- ⚠️ 보안: student_id/content 제거 전에 reviews 의 기존 정책을 "전부" 제거해 fail-closed 로 만든다
--   (rev_select USING(true)·rev_ins·rev_update_own·reviews_select_public·reviews_insert_student·
--    reviews_insert_author·042/한글 정책 등 — student_id 참조 정책이 남으면 컬럼 DROP 실패,
--    permissive 정책이 남으면 123~126 구간 보호 무력화). 123 적용 후 126 적용 전까지 리뷰 기능은
--    닫힌 상태(정책 0개)이며, 이 구간에는 리뷰 트래픽을 재개하지 않는다.
-- 정본 컬럼: id, mentor_id, author_id, rating, body(NOT NULL), subscription_count(nullable),
--   mentor_reply, mentor_replied_at, is_hidden, is_blinded, moderation_state,
--   moderated_at, moderated_by, created_at.
-- 주의: 백필 → 격리 → SET NOT NULL → 중복정리 → UNIQUE 순서. 전 과정 단일 트랜잭션+테이블 잠금.
--   (staging 실적용 시 reviews 0행이라 데이터 단계는 no-op이나, 실데이터 환경 대비 멱등 유지.)
-- --------------------------------------------------------------------------

begin;

lock table public.reviews in share row exclusive mode;

-- (0) fail-closed: reviews 의 모든 정책 제거 (이름 불문 — 아래 컬럼 DROP·구간 보호를 위해 선행) -----
do $$
declare pol record;
begin
  for pol in
    select policyname from pg_policies where schemaname='public' and tablename='reviews'
  loop
    execute format('drop policy if exists %I on public.reviews', pol.policyname);
  end loop;
end $$;

-- (2-1) 컬럼 조건부 정합 (042형/004형 모두 대응) --------------------------------
alter table public.reviews add column if not exists author_id uuid;
alter table public.reviews add column if not exists body text;
alter table public.reviews add column if not exists subscription_count integer;
alter table public.reviews add column if not exists mentor_reply text;
alter table public.reviews add column if not exists mentor_replied_at timestamptz;
alter table public.reviews add column if not exists is_hidden boolean not null default false;
alter table public.reviews add column if not exists is_blinded boolean not null default false;
alter table public.reviews add column if not exists moderation_state text not null default 'visible';
alter table public.reviews add column if not exists moderated_at timestamptz;
alter table public.reviews add column if not exists moderated_by uuid;

-- (2-2) 백필 (042형 잔존 컬럼이 있으면 author_id<-student_id, body<-content) --------
do $$
begin
  if exists (select 1 from information_schema.columns
             where table_schema='public' and table_name='reviews' and column_name='student_id') then
    update public.reviews set author_id = student_id where author_id is null;
  end if;
  if exists (select 1 from information_schema.columns
             where table_schema='public' and table_name='reviews' and column_name='content') then
    update public.reviews set body = content where body is null;
  end if;
end $$;

-- (2-3) NULL/고아 행 격리 — SET NOT NULL 앞 (service_role 전용 아카이브) --------------
create table if not exists public.reviews_quarantine_archive (
  id uuid primary key default gen_random_uuid(),
  original_id uuid, reason text not null, payload jsonb not null,
  archived_at timestamptz not null default now());
alter table public.reviews_quarantine_archive enable row level security;
revoke all on public.reviews_quarantine_archive from public, anon, authenticated;
grant select, insert, update, delete on public.reviews_quarantine_archive to service_role;
drop policy if exists reviews_quarantine_archive_service on public.reviews_quarantine_archive;
create policy reviews_quarantine_archive_service on public.reviews_quarantine_archive
  for all to service_role using (true) with check (true);

create temporary table _rev_quarantine on commit drop as
  select r.id from public.reviews r
  where r.body is null or r.author_id is null
     or not exists (select 1 from public.users u where u.id = r.author_id)
     or not exists (select 1 from public.users u where u.id = r.mentor_id);
insert into public.reviews_quarantine_archive (original_id, reason, payload)
  select r.id, 'null_or_orphan_pre_converge', to_jsonb(r)
  from public.reviews r join _rev_quarantine q on q.id = r.id;
delete from public.reviews r using _rev_quarantine q where q.id = r.id;

-- (2-4) 레거시 NOT NULL/DEFAULT 해소 + 정본 필수 컬럼 확정 -------------------------
alter table public.reviews alter column subscription_count drop default;
do $$
begin
  if exists (select 1 from information_schema.columns
             where table_schema='public' and table_name='reviews'
               and column_name='subscription_count' and is_nullable='NO') then
    alter table public.reviews alter column subscription_count drop not null;
  end if;
end $$;
alter table public.reviews alter column author_id set not null;
alter table public.reviews alter column body set not null;

-- (2-4a) 레거시 student_id/content + 참조 객체 제거 (정책은 (0)에서 이미 전부 제거됨) ------
alter table public.reviews drop constraint if exists reviews_student_id_fkey;
alter table public.reviews drop constraint if exists reviews_one_per_pair;   -- 구 (mentor_id, student_id) 유니크
drop index if exists public.idx_reviews_one_per_pair_compat;
drop index if exists public.idx_reviews_student;
alter table public.reviews drop column if exists student_id;
alter table public.reviews drop column if exists content;

-- (2-6) 인덱스 정본 수렴 -------------------------------------------------------
create index if not exists idx_reviews_author on public.reviews (author_id);
create index if not exists idx_reviews_mentor_created on public.reviews (mentor_id, created_at desc);

-- (3) 중복 (mentor_id, author_id) 정리 후 UNIQUE ------------------------------
create table if not exists public.reviews_duplicates_archive (
  id uuid primary key default gen_random_uuid(),
  original_id uuid, reason text not null, payload jsonb not null,
  archived_at timestamptz not null default now());
alter table public.reviews_duplicates_archive enable row level security;
revoke all on public.reviews_duplicates_archive from public, anon, authenticated;
grant select, insert, update, delete on public.reviews_duplicates_archive to service_role;
drop policy if exists reviews_duplicates_archive_service on public.reviews_duplicates_archive;
create policy reviews_duplicates_archive_service on public.reviews_duplicates_archive
  for all to service_role using (true) with check (true);

create temporary table _rev_dups on commit drop as
  select id from (select id, row_number() over (partition by mentor_id, author_id
                    order by created_at desc, id) as rn from public.reviews) k where k.rn > 1;
insert into public.reviews_duplicates_archive (original_id, reason, payload)
  select r.id, 'dup_mentor_author_pre_unique', to_jsonb(r)
  from public.reviews r join _rev_dups d on d.id = r.id;
delete from public.reviews r using _rev_dups d where d.id = r.id;

create unique index if not exists uq_reviews_mentor_author on public.reviews (mentor_id, author_id);

-- RLS 는 켜진 채로, 정책 0개(fail-closed) 상태로 커밋. 126 적용 시 정본 정책 재생성.
alter table public.reviews enable row level security;

commit;

