-- >>> NATIVE_BASELINE_PART 0142 | supabase/sql/135_mentor_review_stats_rpc.sql | 135_mentor_review_stats_rpc.sql <<<
-- --------------------------------------------------------------------------
-- 135_mentor_review_stats_rpc.sql   (P3-2 · 멘토 리뷰 통계 서버 집계 RPC)
-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과
--   (T1 secdef/search_path · T2 anon/authenticated 실행 · T3 0행 빈결과 · S1 공개 blinded 제외 ·
--    S2 비관리자 include_hidden 강제 공개 · S3 관리자 include). fixture savepoint 롤백·baseline 0행 복원.
--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]
-- 목적: 리뷰 평균/분포를 클라이언트가 최대 500건 fetch 후 집계하던 cap 결함을 제거하고, 서버에서
--   mentor별 count·평균·분포(1~5)를 집계해 반환한다. **집계값만 반환**(원본 행 미노출)하므로 일반
--   사용자가 blinded/hidden 원본을 우회 조회할 수 없다. 공개 통계는 is_hidden/is_blinded 를 제외한다.
--   include_hidden 은 관리자(is_admin())만 허용(그 외는 강제 false).
-- 선행: 042/123/126(reviews 정본: mentor_id·rating·is_hidden·is_blinded). is_admin() 필요.
-- 방식: SECURITY DEFINER 집계 RPC(권한 제한 — 원본 미노출·include_hidden admin 게이트). anon/authenticated 실행 허용.
-- --------------------------------------------------------------------------

create or replace function public.get_mentor_review_stats(
  p_mentor_id uuid,
  p_include_hidden boolean default false
)
returns table(review_count integer, avg_rating numeric, d1 integer, d2 integer, d3 integer, d4 integer, d5 integer)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_include_hidden boolean := coalesce(p_include_hidden, false);
begin
  -- include_hidden 은 관리자만 허용. 그 외에는 공개 집계(hidden/blinded 제외)로 강제.
  if v_include_hidden and not coalesce(public.is_admin(), false) then
    v_include_hidden := false;
  end if;

  return query
  select
    count(*)::integer,
    case when count(*) > 0 then round(avg(r.rating)::numeric, 1) else null end,
    count(*) filter (where round(r.rating) = 1)::integer,
    count(*) filter (where round(r.rating) = 2)::integer,
    count(*) filter (where round(r.rating) = 3)::integer,
    count(*) filter (where round(r.rating) = 4)::integer,
    count(*) filter (where round(r.rating) = 5)::integer
  from public.reviews r
  where r.mentor_id = p_mentor_id
    and (
      v_include_hidden
      or (coalesce(r.is_hidden, false) = false and coalesce(r.is_blinded, false) = false)
    );
end;
$$;

comment on function public.get_mentor_review_stats(uuid, boolean) is
  'P3-2: 멘토 리뷰 통계(count·avg·분포) 서버 집계. 집계값만 반환(원본 미노출). 공개는 hidden/blinded 제외, include_hidden 은 is_admin() 전용.';

revoke all on function public.get_mentor_review_stats(uuid, boolean) from public;
grant execute on function public.get_mentor_review_stats(uuid, boolean) to anon, authenticated, service_role;

-- >>> NATIVE_BASELINE_PART 0143 | supabase/sql/136_p1_8a_question_room_atomic_rpc.sql | 136_p1_8a_question_room_atomic_rpc.sql <<<
-- 136_p1_8a_question_room_atomic_rpc.sql
-- P1-8A: 구독 질문방 원자 RPC + free_question_usage.thread_id 수렴 (정본 수렴 파일)
--
-- 계보 메모
--   * 설계 정본: docs/audit/p1-8a_question_room_rpc_plan.md (원래 127_question_thread_rpcs.sql 로 예약).
--   * 본 정의는 PR #43(브랜치 claude/v16-web-db-autonomous-*)에서 staging 에 선적용됐다.
--     PR #43 의 파일 번호 130 은 이 브랜치의 130_shortform_scrap_reaction 과 충돌하므로,
--     정본 브랜치(PR #42)에서 다음 빈 고유 번호 136 으로 수렴한다. (131=P1-13 예약, 127=설계 예약 gap.)
--   * 선행 의존: 132_notification_outbox_foundation.sql (P1-11F: notification_outbox + record_domain_notification).
--     clean-install 시 132 가 반드시 136 보다 먼저 적용돼야 한다.
--   * 멱등(create or replace / add ... if not exists). staging 에 이미 적용된 부분은 no-op,
--     UNIQUE(thread_id)/UNIQUE(storage_path)/일반 create RPC/enhanced register 는 델타로 수렴.
--
-- 목적
--   * 무료 질문권 소비(free_question_usage)와 스레드 생성의 비원자·오짝 제거.
--   * free_question_usage.thread_id 수렴(FK ON DELETE SET NULL + UNIQUE) → 정확 1:1 링크.
--   * 생성 RPC가 무료/활성구독 자격을 서버에서 분기.
--   * 멘토 첫 메시지/첨부만 answered 전이 + record_domain_notification exactly-once.
--   * 계정상태·차단·멘토승인·자격 서버 재검사.
--
-- 전환 정책 (P1-8B 는 별도 · WAITING_EXTERNAL_APP)
--   * 순수 추가형. 기존 direct-write 정책·GRANT(qt_write_via_room/qm_insert/fqu_insert_own/
--     question_attachments_insert_via_room/049 storage) 유지. 앱 신버전 전 제거·revoke·open→pending 이관 금지.
--   * 무료사용 FK CASCADE 금지 → thread_id FK ON DELETE SET NULL.
--
-- 잠금값: 무료 총 7 / 멘토당 3 / 가입 후 7일. 주간(구독): limited4/standard9/premium999(get_weekly_question_usage).
--         status CHECK pending/answered/confirmed/open/closed/archived. mastery unknown/wrong/review/mastered.

begin;
set local lock_timeout = '5s';

-- ── 1) free_question_usage.thread_id 수렴 (추가형 + UNIQUE) ──
alter table public.free_question_usage add column if not exists thread_id uuid;

do $$
begin
  if not exists (select 1 from pg_constraint
    where conname='free_question_usage_thread_id_fkey' and conrelid='public.free_question_usage'::regclass) then
    alter table public.free_question_usage
      add constraint free_question_usage_thread_id_fkey
      foreign key (thread_id) references public.question_threads(id) on delete set null;
  end if;
  -- UNIQUE(thread_id): NULL 다중 허용(레거시), 신규 링크는 스레드당 1건.
  if not exists (select 1 from pg_constraint
    where conname='free_question_usage_thread_id_key' and conrelid='public.free_question_usage'::regclass) then
    alter table public.free_question_usage
      add constraint free_question_usage_thread_id_key unique (thread_id);
  end if;
end$$;

create index if not exists free_question_usage_thread_id_idx
  on public.free_question_usage (thread_id);

-- ── 1b) question_attachments.storage_path UNIQUE (0행 → 중복 대사 불필요) ──
do $$
begin
  if not exists (select 1 from pg_constraint
    where conname='question_attachments_storage_path_key' and conrelid='public.question_attachments'::regclass) then
    alter table public.question_attachments
      add constraint question_attachments_storage_path_key unique (storage_path);
  end if;
end$$;

-- ── 2) 질문 스레드 원자 생성 RPC (일반: 무료/활성구독 서버 분기, 학생 전용) ──
create or replace function public.qna_create_question_thread(
  p_room_id uuid,
  p_title text,
  p_subject text default null,
  p_topic text default null,
  p_first_message_body text default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_uid uuid := auth.uid();
  v_student uuid;
  v_mentor uuid;
  v_status text;
  v_suspended_until timestamptz;
  v_created_at timestamptz;
  v_total int;
  v_per int;
  v_subject text;
  v_thread_id uuid;
  v_message_id uuid;
  v_has_active_sub boolean;
  v_usage json;
  v_path text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_title is null or btrim(p_title) = '' then raise exception 'TITLE_REQUIRED'; end if;

  select student_id, mentor_id into v_student, v_mentor
  from public.mentor_student_rooms where id = p_room_id;
  if not found then raise exception 'ROOM_NOT_FOUND'; end if;

  if v_uid <> v_student then
    if v_uid = v_mentor then raise exception 'MENTOR_CANNOT_CREATE_THREAD';
    else raise exception 'NOT_ROOM_PARTY'; end if;
  end if;

  -- 학생 단위 직렬화(무료 총/멘토별 한도 + 주간 한도 경쟁 안전).
  perform 1 from public.users where id = v_student for update;

  select status, suspended_until, created_at
    into v_status, v_suspended_until, v_created_at
  from public.users where id = v_student;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active')) = 'suspended'
     and (v_suspended_until is null or v_suspended_until > now()) then
    raise exception 'ACCOUNT_SUSPENDED';
  end if;

  if exists (select 1 from public.user_blocks
    where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then
    raise exception 'BLOCKED';
  end if;

  if not public.individual_question_user_is_approved_mentor(v_mentor) then
    raise exception 'MENTOR_NOT_APPROVED';
  end if;

  -- 자격 분기: 활성 구독 vs 무료.
  v_has_active_sub := exists (
    select 1 from public.subscriptions
    where student_id = v_student and mentor_id = v_mentor and lower(coalesce(status,'')) = 'active'
  );

  if v_has_active_sub then
    v_usage := public.get_weekly_question_usage(v_student, v_mentor);
    if not coalesce((v_usage->>'can_ask')::boolean, false) then
      raise exception 'WEEKLY_LIMIT_EXHAUSTED';
    end if;
    v_path := 'subscription';
  else
    if v_created_at is not null and now() >= v_created_at + interval '7 days' then
      raise exception 'FREE_QUOTA_EXPIRED';
    end if;
    select count(*) into v_total from public.free_question_usage where student_id = v_student;
    if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
    select count(*) into v_per from public.free_question_usage
      where student_id = v_student and mentor_id = v_mentor;
    if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    v_path := 'free';
  end if;

  v_subject := nullif(btrim(coalesce(p_subject,'')), '');
  if v_subject is not null and not exists (select 1 from public.subjects where code = v_subject) then
    v_subject := null;
  end if;

  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)
  values (p_room_id, btrim(p_title), 'pending', v_subject, nullif(btrim(coalesce(p_topic,'')), ''))
  returning id into v_thread_id;

  if p_first_message_body is not null and btrim(p_first_message_body) <> '' then
    insert into public.question_messages (thread_id, author_id, body)
    values (v_thread_id, v_student, btrim(p_first_message_body))
    returning id into v_message_id;
  end if;

  if v_path = 'free' then
    insert into public.free_question_usage (student_id, mentor_id, thread_id)
    values (v_student, v_mentor, v_thread_id);
  end if;

  return jsonb_build_object(
    'ok', true, 'thread_id', v_thread_id, 'message_id', v_message_id,
    'path', v_path, 'used_free_quota', (v_path = 'free')
  );
end;
$$;

-- ── 2b) 무료 전용 진입점(레거시 호환): 일반 RPC 로 위임(추가형 — drop 금지). ──
create or replace function public.qna_create_free_question_thread(
  p_room_id uuid,
  p_title text,
  p_subject text default null,
  p_topic text default null,
  p_first_message_body text default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  return public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);
end;
$$;

-- ── 3) 메시지 append RPC — 멘토 첫 답변만 answered 전이 + exactly-once 알림 ──
create or replace function public.qna_append_message(
  p_thread_id uuid,
  p_body text
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_uid uuid := auth.uid();
  v_room uuid;
  v_student uuid;
  v_mentor uuid;
  v_status text;
  v_thread_status text;
  v_first_answered timestamptz;
  v_message_id uuid;
  v_is_mentor boolean;
  v_transitioned boolean := false;
  v_mentor_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_body is null or btrim(p_body) = '' then raise exception 'BODY_REQUIRED'; end if;

  select t.mentor_student_room_id, t.status, t.first_answered_at
    into v_room, v_thread_status, v_first_answered
  from public.question_threads t where t.id = p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;

  select student_id, mentor_id into v_student, v_mentor
  from public.mentor_student_rooms where id = v_room;

  if v_uid = v_mentor then v_is_mentor := true;
  elsif v_uid = v_student then v_is_mentor := false;
  else raise exception 'NOT_ROOM_PARTY'; end if;

  select status into v_status from public.users where id = v_uid;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;

  if v_thread_status in ('confirmed','closed','archived') then raise exception 'THREAD_LOCKED'; end if;

  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then
    raise exception 'MENTOR_NOT_APPROVED';
  end if;

  insert into public.question_messages (thread_id, author_id, body)
  values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;

  if v_is_mentor and v_first_answered is null then
    update public.question_threads
      set status='answered', first_answered_at=now(), updated_at=now()
    where id = p_thread_id and first_answered_at is null;
    v_transitioned := true;
    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토')
      into v_mentor_name from public.users where id = v_mentor;
    perform public.record_domain_notification(
      v_student,
      'question_answered:' || p_thread_id::text,
      'question_answered:' || p_thread_id::text,
      'question_answered', '새 답변이 도착했어요',
      coalesce(v_mentor_name,'멘토') || '님이 답변을 남겼습니다.',
      '/question-room/' || v_room::text || '?thread=' || p_thread_id::text,
      jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id),
      jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'message_id', v_message_id, 'answered_transition', v_transitioned);
end;
$$;

-- ── 4) 학생 확인 RPC (answered→confirmed) ──
create or replace function public.qna_confirm_thread(p_thread_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_status text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select t.mentor_student_room_id, t.status into v_room, v_status
  from public.question_threads t where t.id = p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id into v_student from public.mentor_student_rooms where id = v_room;
  if v_uid <> v_student then raise exception 'STUDENT_ONLY'; end if;
  if v_status = 'confirmed' then return jsonb_build_object('ok', true, 'thread_id', p_thread_id); end if;
  if v_status <> 'answered' then raise exception 'NOT_ANSWERED'; end if;
  update public.question_threads
    set status='confirmed', confirmed_at=coalesce(confirmed_at, now()), updated_at=now()
  where id = p_thread_id;
  return jsonb_build_object('ok', true, 'thread_id', p_thread_id);
end;
$$;

-- ── 5) 오답 표시 RPC (학생) ──
create or replace function public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean default true)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_uid uuid := auth.uid(); v_room uuid; v_student uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select t.mentor_student_room_id into v_room
  from public.question_threads t where t.id = p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id into v_student from public.mentor_student_rooms where id = v_room;
  if v_uid <> v_student then raise exception 'STUDENT_ONLY'; end if;
  update public.question_threads
    set is_wrong_answer=coalesce(p_is_wrong,true),
        mastery_status=case when coalesce(p_is_wrong,true) then 'wrong' else 'unknown' end,
        updated_at=now()
  where id = p_thread_id;
  return jsonb_build_object('ok', true, 'thread_id', p_thread_id, 'is_wrong_answer', coalesce(p_is_wrong,true));
end;
$$;

-- ── 6) 첨부 등록 RPC — 경로 thread-id 검증 + 멘토 첫 첨부 answered 전이 + exactly-once 알림 ──
create or replace function public.qna_register_attachment(
  p_thread_id uuid,
  p_storage_path text,
  p_file_name text default null,
  p_mime_type text default null,
  p_message_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_uid uuid := auth.uid();
  v_room uuid;
  v_student uuid;
  v_mentor uuid;
  v_thread_status text;
  v_first_answered timestamptz;
  v_att_id uuid;
  v_is_mentor boolean;
  v_transitioned boolean := false;
  v_mentor_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_path is null or btrim(p_storage_path) = '' then raise exception 'STORAGE_PATH_REQUIRED'; end if;

  select t.mentor_student_room_id, t.status, t.first_answered_at
    into v_room, v_thread_status, v_first_answered
  from public.question_threads t where t.id = p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;

  select student_id, mentor_id into v_student, v_mentor
  from public.mentor_student_rooms where id = v_room;
  if v_uid = v_mentor then v_is_mentor := true;
  elsif v_uid = v_student then v_is_mentor := false;
  else raise exception 'NOT_ROOM_PARTY'; end if;

  if v_thread_status in ('confirmed','closed','archived') then raise exception 'THREAD_LOCKED'; end if;

  -- 경로 thread-id 검증: {room}/{thread}/... 프리픽스 (buildObjectPath 계약).
  if p_storage_path not like (v_room::text || '/' || p_thread_id::text || '/%') then
    raise exception 'STORAGE_PATH_MISMATCH';
  end if;

  if p_message_id is not null and not exists (
    select 1 from public.question_messages m where m.id = p_message_id and m.thread_id = p_thread_id
  ) then raise exception 'MESSAGE_THREAD_MISMATCH'; end if;

  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)
  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type)
  returning id into v_att_id;

  if v_is_mentor and v_first_answered is null then
    update public.question_threads
      set status='answered', first_answered_at=now(), updated_at=now()
    where id = p_thread_id and first_answered_at is null;
    v_transitioned := true;
    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토')
      into v_mentor_name from public.users where id = v_mentor;
    perform public.record_domain_notification(
      v_student,
      'question_answered:' || p_thread_id::text,
      'question_answered:' || p_thread_id::text,
      'question_answered', '새 답변이 도착했어요',
      coalesce(v_mentor_name,'멘토') || '님이 파일을 보냈습니다.',
      '/question-room/' || v_room::text || '?thread=' || p_thread_id::text,
      jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id),
      jsonb_build_object('room_id', v_room, 'thread_id', p_thread_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'attachment_id', v_att_id, 'answered_transition', v_transitioned);
end;
$$;

-- ── 7) 권한: authenticated + service_role. public·anon revoke. ──
revoke all on function public.qna_create_question_thread(uuid,text,text,text,text) from public, anon;
revoke all on function public.qna_create_free_question_thread(uuid,text,text,text,text) from public, anon;
revoke all on function public.qna_append_message(uuid,text) from public, anon;
revoke all on function public.qna_confirm_thread(uuid) from public, anon;
revoke all on function public.qna_flag_wrong_answer(uuid,boolean) from public, anon;
revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon;

grant execute on function public.qna_create_question_thread(uuid,text,text,text,text) to authenticated, service_role;
grant execute on function public.qna_create_free_question_thread(uuid,text,text,text,text) to authenticated, service_role;
grant execute on function public.qna_append_message(uuid,text) to authenticated, service_role;
grant execute on function public.qna_confirm_thread(uuid) to authenticated, service_role;
grant execute on function public.qna_flag_wrong_answer(uuid,boolean) to authenticated, service_role;
grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role;

commit;

-- §V (rollback-only fixture): 무료/구독 경로 생성, thread_id UNIQUE, storage_path UNIQUE,
--   append/register 멘토 첫답 answered+exactly-once, confirm(answered 선행), wrong, 비당사자·한도 거부.
-- pending-refund lock 경계(결정 C)는 P1-13 billing-event 정본 확정 시 helper 로 교체 = WAITING_P1_13.

-- >>> NATIVE_BASELINE_PART 0144 | supabase/sql/137_p3_8_realtime_messages_threads.sql | 137_p3_8_realtime_messages_threads.sql <<<
-- 137_p3_8_realtime_messages_threads.sql
-- P3-8: 질문방 실시간 — supabase_realtime publication 에 question_messages / question_threads 추가.
--
-- 계보: PR #43 에서 staging 선적용(파일 131). 131 은 정본 브랜치에서 P1-13 예약 번호라 137 로 수렴.
-- 배경: 117 은 question_attachments 만 추가 → 메시지 신규/스레드 상태전이 실시간 미반영(재조회 폴백).
-- 안전: 두 테이블 모두 SELECT RLS(qm_select/qt_select_via_room) → 브로드캐스트도 당사자만 수신.
--       replica identity 는 attachments 와 동일 default(PK). 멱등.
-- 선행: 136(P1-8A) 이후. 038/117(실시간 계보).

do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='question_messages') then
    execute 'alter publication supabase_realtime add table public.question_messages';
  end if;
  if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='question_threads') then
    execute 'alter publication supabase_realtime add table public.question_threads';
  end if;
end$$;

-- §V: select tablename from pg_publication_tables where pubname='supabase_realtime' and schemaname='public'
--       and tablename in ('question_messages','question_threads','question_attachments'); → 3행.

-- >>> NATIVE_BASELINE_PART 0145 | supabase/sql/138_p3_9_student_nickname_rpc_anon_revoke.sql | 138_p3_9_student_nickname_rpc_anon_revoke.sql <<<
-- 138_p3_9_student_nickname_rpc_anon_revoke.sql
-- P3-9(부분): 학생 PII 반환 RPC 의 anon/public 실행권 회수(심층방어).
--
-- 계보: PR #43 에서 staging 선적용(파일 132). 132 는 정본 브랜치에서 notification_outbox_foundation 과
--       충돌하므로 138 로 수렴.
-- get_mentor_student_nicknames(uuid[]) 는 SECURITY DEFINER 로 users.nickname/full_name(PII)을 반환한다.
-- 본문은 이미 (a) auth.uid() not null (b) 호출자가 custom_request_orders 의 해당 학생 멘토일 때만 반환하도록
-- 제한하지만, Supabase 기본 권한으로 anon 에도 EXECUTE 가 부여돼 있었다. anon 은 결과가 비지만 PII 정의함수를
-- anon 이 호출 가능한 상태 자체를 제거한다.
--
-- P3-9 나머지(활성구독/질문방 당사자 기준으로 노출 인가 재정의)는 현행 custom_request_orders 기준과
-- 다른 인가 집합으로의 기능 변경이라 제품 결정 필요 = DEFERRED_PRODUCT_DECISION.

revoke all on function public.get_mentor_student_nicknames(uuid[]) from anon, public;

-- §V: select grantee from information_schema.routine_privileges
--     where specific_schema='public' and routine_name='get_mentor_student_nicknames'; → {authenticated, service_role}(및 owner).

-- >>> NATIVE_BASELINE_PART 0146 | supabase/sql/139_p1_8a_attachment_storage_contract.sql | 139_p1_8a_attachment_storage_contract.sql <<<
-- 139_p1_8a_attachment_storage_contract.sql
-- P1-8A 첨부 Storage 계약 완결 — 136 을 수정하지 않는 수렴 보정.
--
-- 배경: 049 는 question-room-attachments INSERT(party via path)·SELECT(party/admin) 정책만 두고
--       DELETE 정책이 없어 보상 삭제가 조용히 실패했다. 등록 RPC 도 storage 객체 존재·owner 를 대조하지 않았다.
-- 안전: 추가형(DELETE 정책 신설) + INSERT 정책 조건 강화(당사자 + 경로 thread 소속 + 쓰기가능 상태).
--       기존 direct-write 테이블 정책·049 SELECT/INSERT 존재 자체는 유지(앱 전환 전 최종 제거 금지).
-- 선행: 136(RPC), 049(qra storage), 132(record_domain_notification).

begin;
set local lock_timeout='5s';

-- 경로의 thread 세그먼트가 room 에 속하고 쓰기 가능한 상태인지 검사(경로 = {room}/{thread}/{uuid}-name).
create or replace function public.qra_thread_writable_for_path(p_name text)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1
    from public.question_threads t
    where t.id = nullif(split_part(p_name, '/', 2), '')::uuid
      and t.mentor_student_room_id = public.qra_room_uuid_from_path(p_name)
      and coalesce(t.status, '') in ('pending','open','answered')
  );
$$;
revoke all on function public.qra_thread_writable_for_path(text) from public, anon;
grant execute on function public.qra_thread_writable_for_path(text) to authenticated, service_role;

-- 업로드 INSERT 정책 강화: 당사자 + 경로 thread 소속 + 쓰기가능 상태.
--  (자격(무료/구독)은 등록 RPC 가 authoritative 하게 재검사하고, 실패 시 미등록 객체를 보상 삭제한다.)
drop policy if exists qra_storage_insert_party on storage.objects;
create policy qra_storage_insert_party on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'question-room-attachments'
    and public.user_is_room_party_for_qra_path(name)
    and public.qra_thread_writable_for_path(name)
  );

-- 보상 DELETE 정책: 본인 소유(owner_id=auth.uid()) + 미등록 객체만. 활성 스레드 조건 없음.
--  등록된 question_attachments.storage_path 객체는 삭제 불가. 타인 객체 삭제 거부.
drop policy if exists qra_storage_delete_unregistered_owner on storage.objects;
create policy qra_storage_delete_unregistered_owner on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'question-room-attachments'
    and owner_id = (select auth.uid())::text
    and not exists (
      select 1 from public.question_attachments a where a.storage_path = storage.objects.name
    )
  );

-- 등록 RPC 강화: storage 객체 존재 + 정확 bucket + owner_id=auth.uid() 대조 추가.
create or replace function public.qna_register_attachment(
  p_thread_id uuid, p_storage_path text, p_file_name text default null, p_mime_type text default null, p_message_id uuid default null
) returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;
  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_path is null or btrim(p_storage_path)='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered
    from public.question_threads t where t.id=p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;
  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception 'NOT_ROOM_PARTY'; end if;
  if v_thread_status in ('confirmed','closed','archived') then raise exception 'THREAD_LOCKED'; end if;
  -- 경로 thread-id 일치({room}/{thread}/...).
  if p_storage_path not like (v_room::text || '/' || p_thread_id::text || '/%') then raise exception 'STORAGE_PATH_MISMATCH'; end if;
  -- storage 객체 존재 + 정확 bucket + owner_id=auth.uid().
  if not exists (
    select 1 from storage.objects o
    where o.bucket_id='question-room-attachments' and o.name = btrim(p_storage_path)
      and o.owner_id = v_uid::text
  ) then raise exception 'STORAGE_OBJECT_NOT_OWNED'; end if;
  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception 'MESSAGE_THREAD_MISMATCH'; end if;

  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)
  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;

  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토') into v_mentor_name from public.users where id=v_mentor;
    perform public.record_domain_notification(v_student, 'question_answered:'||p_thread_id::text, 'question_answered:'||p_thread_id::text,
      'question_answered','새 답변이 도착했어요', coalesce(v_mentor_name,'멘토')||'님이 파일을 보냈습니다.',
      '/question-room/'||v_room::text||'?thread='||p_thread_id::text,
      jsonb_build_object('room_id',v_room,'thread_id',p_thread_id), jsonb_build_object('room_id',v_room,'thread_id',p_thread_id));
  end if;
  return jsonb_build_object('ok',true,'attachment_id',v_att_id,'answered_transition',v_transitioned);
end; $$;

revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon;
grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role;

commit;

-- §V: (a) INSERT 정책 = party+thread+writable, (b) DELETE 정책 owner+미등록만,
--     (c) 등록 RPC 가 미소유/미존재 객체 STORAGE_OBJECT_NOT_OWNED 거부, (d) 등록된 객체 DELETE 거부.

-- >>> NATIVE_BASELINE_PART 0147 | supabase/sql/140_p3_9_student_nickname_subscription_room_scope.sql | 140_p3_9_student_nickname_subscription_room_scope.sql <<<
-- 140_p3_9_student_nickname_subscription_room_scope.sql
-- P3-9 완결 — `get_mentor_student_nicknames` 노출 인가를 v16(1) 정책으로 재정의.
--
-- 정책: 호출 멘토는 다음 관계의 학생 이름만 조회할 수 있다.
--   (a) 호출 멘토와 **활성 구독** 관계, 또는
--   (b) 호출 멘토와 **실제 질문방(mentor_student_rooms) 당사자** 관계.
-- custom_request_orders 만 존재하는 관계는 (a)/(b) 를 충족하지 않으면 반환 근거가 아니다.
--
-- 138(anon/public revoke)을 수정하지 않고 다음 고유 번호로 본문을 재정의한다.
-- - 호출 멘토는 auth.uid() 에서 서버가 도출(클라이언트 mentor ID 신뢰 금지).
-- - 타 멘토의 학생 열거 금지(관계는 mentor_id = auth.uid() 로만 성립).
-- - anon/public 실행 금지 유지, SECURITY DEFINER + 고정 search_path, service_role 허용.

create or replace function public.get_mentor_student_nicknames(p_student_ids uuid[])
returns table(id uuid, nickname text, full_name text)
language sql
stable
security definer
set search_path to 'public'
as $$
  select u.id, u.nickname, u.full_name
  from public.users u
  where p_student_ids is not null
    and array_length(p_student_ids, 1) is not null
    and u.id = any (p_student_ids)
    and (select auth.uid()) is not null
    and (
      exists (
        select 1 from public.subscriptions s
        where s.mentor_id = (select auth.uid())
          and s.student_id = u.id
          and lower(coalesce(s.status, '')) = 'active'
      )
      or exists (
        select 1 from public.mentor_student_rooms r
        where r.mentor_id = (select auth.uid())
          and r.student_id = u.id
      )
    );
$$;

revoke all on function public.get_mentor_student_nicknames(uuid[]) from public, anon;
grant execute on function public.get_mentor_student_nicknames(uuid[]) to authenticated, service_role;

-- §V(rollback-only): 활성구독 학생→반환 · 질문방 학생→반환 · custom_order만/무관계 학생→미반환 ·
--   타 멘토가 호출→미반환. grantee={authenticated,service_role}.

-- >>> NATIVE_BASELINE_PART 0148 | supabase/sql/141_p1_8a_direct_write_guards.sql | 141_p1_8a_direct_write_guards.sql <<<
-- 141_p1_8a_direct_write_guards.sql
-- P1-8A 최종 보안 마감 — 앱 호환 direct-write 우회 방어(서버 트리거) + 업로드 정책 계정/멘토 강제.
--
-- 배경: 앱 전환 전 direct-write 정책(qt_write_via_room/qt_update_via_room/qm_insert/
--       question_attachments_insert_via_room/fqu_insert_own)은 유지한다. 그러나 직접 호출로
--       워크플로 불변식을 우회할 수 없도록 DB 트리거로 강제한다.
-- 판별: 신규 qna_* RPC 는 SECURITY DEFINER(owner=postgres)라 실행 중 current_user='postgres'.
--       PostgREST 직접 write 는 current_user='authenticated'/'anon'. → 직접 write 만 가드한다.
-- 안전: 순수 추가형(트리거·정책 강화). 139 미수정. 무료 한도는 기존 check_free_question_usage_limits
--       트리거가 유지, fqu RLS 는 student_id=auth.uid() 로 타인 조작 차단.
-- 선행: 049·136·139.

begin;
set local lock_timeout='5s';

-- 직접(비신뢰) writer 판별: authenticated/anon 세션의 직접 테이블 write.
create or replace function public.qna_is_direct_untrusted_writer()
returns boolean language sql stable as $$
  select current_user in ('authenticated','anon');
$$;

-- ── Part 1: 업로드 INSERT 정책에 계정 활성 + (멘토면)승인 강제 추가 ──
create or replace function public.qra_uploader_allowed_for_path(p_name text)
returns boolean language plpgsql stable security definer set search_path to 'public' as $$
declare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;
begin
  if v_uid is null then return false; end if;
  v_room := public.qra_room_uuid_from_path(p_name);
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;
  if v_student is null then return false; end if;
  -- 계정 활성(업로더).
  select status into v_status from public.users where id = v_uid;
  if lower(coalesce(v_status,'active')) = 'banned' then return false; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' then
    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;
  end if;
  -- 멘토 업로더면 승인 필수.
  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;
  return true;
end;
$$;
revoke all on function public.qra_uploader_allowed_for_path(text) from public, anon;
grant execute on function public.qra_uploader_allowed_for_path(text) to authenticated, service_role;

drop policy if exists qra_storage_insert_party on storage.objects;
create policy qra_storage_insert_party on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'question-room-attachments'
    and public.user_is_room_party_for_qra_path(name)
    and public.qra_thread_writable_for_path(name)
    and public.qra_uploader_allowed_for_path(name)
  );

-- ── Part 2: question_threads 직접 write 워크플로 가드 ──
create or replace function public.qt_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select student_id, mentor_id into v_student, v_mentor
    from public.mentor_student_rooms where id = NEW.mentor_student_room_id;
  if TG_OP = 'INSERT' then
    if coalesce(NEW.status,'pending') not in ('pending','open') then raise exception 'DIRECT_INSERT_STATUS_FORBIDDEN'; end if;
    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception 'DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN'; end if;
    return NEW;
  end if;
  -- UPDATE: role-correct workflow transitions only.
  if NEW.status is distinct from OLD.status then
    if NEW.status = 'answered' and v_uid is distinct from v_mentor then raise exception 'DIRECT_ANSWERED_MENTOR_ONLY'; end if;
    if NEW.status = 'confirmed' and v_uid is distinct from v_student then raise exception 'DIRECT_CONFIRM_STUDENT_ONLY'; end if;
  end if;
  if NEW.first_answered_at is distinct from OLD.first_answered_at and v_uid is distinct from v_mentor then
    raise exception 'DIRECT_FIRST_ANSWERED_MENTOR_ONLY';
  end if;
  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status)
     and v_uid is distinct from v_student then
    raise exception 'DIRECT_WRONG_FLAG_STUDENT_ONLY';
  end if;
  return NEW;
end;
$$;
drop trigger if exists trg_qt_direct_write_guard on public.question_threads;
create trigger trg_qt_direct_write_guard before insert or update on public.question_threads
  for each row execute function public.qt_direct_write_guard();

-- ── Part 2: question_messages 직접 write — 종료 스레드 거부 ──
create or replace function public.qm_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select status into v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_MSG_THREAD_LOCKED'; end if;
  return NEW;
end;
$$;
drop trigger if exists trg_qm_direct_write_guard on public.question_messages;
create trigger trg_qm_direct_write_guard before insert on public.question_messages
  for each row execute function public.qm_direct_write_guard();

-- ── Part 2: question_attachments 직접 write — 종료 스레드·경로/owner 위조 거부 ──
create or replace function public.qa_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_room uuid; v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_ATT_THREAD_LOCKED'; end if;
  if NEW.storage_path is null or NEW.storage_path not like (v_room::text || '/' || NEW.thread_id::text || '/%') then
    raise exception 'DIRECT_ATT_PATH_FORGERY';
  end if;
  if not exists (
    select 1 from storage.objects o
    where o.bucket_id='question-room-attachments' and o.name = NEW.storage_path and o.owner_id = auth.uid()::text
  ) then raise exception 'DIRECT_ATT_OBJECT_NOT_OWNED'; end if;
  return NEW;
end;
$$;
drop trigger if exists trg_qa_direct_write_guard on public.question_attachments;
create trigger trg_qa_direct_write_guard before insert on public.question_attachments
  for each row execute function public.qa_direct_write_guard();

commit;

-- §V(rollback-only): RPC(postgres) 경로 무영향 · 직접 authenticated 의 타역할 status/first_answered/
--   wrong 변경 거부 · 종료 스레드 메시지/첨부 거부 · 경로/owner 위조 거부 · 업로드 정책 정지계정/미승인멘토 거부.

-- >>> NATIVE_BASELINE_PART 0149 | supabase/sql/142_p1_8a_pending_refund_lock.sql | 142_p1_8a_pending_refund_lock.sql <<<
-- 142_p1_8a_pending_refund_lock.sql
-- P1-8A 즉시 연동 — 활성 구독을 질문 자격으로 인정하기 전 pending refund 잠금 검사.
--
-- 계약(결정 C): 활성 구독 기반 자격을 인정하기 전에
--   1) 해당 subscription 행 FOR UPDATE 잠금
--   2) 잠근 구독의 두 canonical 구독 환불 유형(subscription_prorated / subscription_mentor_suspended)
--   3) live pending refund 존재를 별도 statement 로 검사
--   4) pending 이면 새 질문·후속 메시지·첨부(학생 측)를 거부.
-- 클라이언트 사전 검사에 의존하지 않는다. 무료 스레드(활성구독 없음)는 미적용.
-- P1-13 billing-event 정본 확정 시 last_billing_event_id 기준 helper 로 교체 가능한 경계.
--
-- 136/139 를 수정하지 않고 create/append/register RPC 를 본문 포함 재정의(create or replace). 순수 로직 추가.
-- 선행: 131(refunds/subscriptions)·136·139.

begin;
set local lock_timeout='5s';

-- 잠근 구독의 live pending 구독 환불 존재 여부(별도 statement 로 호출).
create or replace function public.qna_subscription_has_live_refund(p_subscription_id uuid)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1 from public.refunds r
    where r.subscription_id = p_subscription_id
      and r.status = 'pending'
      and r.request_type in ('subscription_prorated','subscription_mentor_suspended')
  );
$$;
revoke all on function public.qna_subscription_has_live_refund(uuid) from public, anon;
grant execute on function public.qna_subscription_has_live_refund(uuid) to authenticated, service_role;

-- create: 구독 경로에서 subscription FOR UPDATE + pending-refund 게이트.
create or replace function public.qna_create_question_thread(
  p_room_id uuid, p_title text, p_subject text default null, p_topic text default null, p_first_message_body text default null
) returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;
  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;
  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_title is null or btrim(p_title)='' then raise exception 'TITLE_REQUIRED'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;
  if not found then raise exception 'ROOM_NOT_FOUND'; end if;
  if v_uid <> v_student then
    if v_uid = v_mentor then raise exception 'MENTOR_CANNOT_CREATE_THREAD'; else raise exception 'NOT_ROOM_PARTY'; end if;
  end if;
  perform 1 from public.users where id=v_student for update;
  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;
  if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active'))='suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception 'BLOCKED'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;

  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active');
  if v_has_active_sub then
    -- 결정 C: 활성 구독 FOR UPDATE 잠금 후 별도 statement 로 live pending refund 검사.
    select id into v_sub_id from public.subscriptions
      where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active' for update;
    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then
      raise exception 'SUBSCRIPTION_REFUND_PENDING';
    end if;
    v_usage := public.get_weekly_question_usage(v_student, v_mentor);
    if not coalesce((v_usage->>'can_ask')::boolean, false) then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    v_path := 'subscription';
  else
    if v_created_at is not null and now() >= v_created_at + interval '7 days' then raise exception 'FREE_QUOTA_EXPIRED'; end if;
    select count(*) into v_total from public.free_question_usage where student_id=v_student;
    if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;
    if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    v_path := 'free';
  end if;

  v_subject := nullif(btrim(coalesce(p_subject,'')),'');
  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then v_subject := null; end if;
  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)
  values (p_room_id, btrim(p_title), 'pending', v_subject, nullif(btrim(coalesce(p_topic,'')),'')) returning id into v_thread_id;
  if p_first_message_body is not null and btrim(p_first_message_body) <> '' then
    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;
  end if;
  if v_path='free' then
    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id);
  end if;
  return jsonb_build_object('ok',true,'thread_id',v_thread_id,'message_id',v_message_id,'path',v_path,'used_free_quota',(v_path='free'));
end; $$;

-- append: 학생 후속 메시지도 활성 구독 pending-refund 게이트.
create or replace function public.qna_append_message(p_thread_id uuid, p_body text)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;
  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text; v_sub_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_body is null or btrim(p_body)='' then raise exception 'BODY_REQUIRED'; end if;
  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered
    from public.question_threads t where t.id=p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;
  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception 'NOT_ROOM_PARTY'; end if;
  select status into v_status from public.users where id=v_uid;
  if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if v_thread_status in ('confirmed','closed','archived') then raise exception 'THREAD_LOCKED'; end if;
  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트.
  if not v_is_mentor then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active' for update;
    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception 'SUBSCRIPTION_REFUND_PENDING'; end if;
  end if;

  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토') into v_mentor_name from public.users where id=v_mentor;
    perform public.record_domain_notification(v_student, 'question_answered:'||p_thread_id::text, 'question_answered:'||p_thread_id::text,
      'question_answered','새 답변이 도착했어요', coalesce(v_mentor_name,'멘토')||'님이 답변을 남겼습니다.',
      '/question-room/'||v_room::text||'?thread='||p_thread_id::text,
      jsonb_build_object('room_id',v_room,'thread_id',p_thread_id), jsonb_build_object('room_id',v_room,'thread_id',p_thread_id));
  end if;
  return jsonb_build_object('ok',true,'message_id',v_message_id,'answered_transition',v_transitioned);
end; $$;

-- register: 학생 첨부도 활성 구독 pending-refund 게이트(139 계약 + refund).
create or replace function public.qna_register_attachment(
  p_thread_id uuid, p_storage_path text, p_file_name text default null, p_mime_type text default null, p_message_id uuid default null
) returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;
  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text; v_sub_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_path is null or btrim(p_storage_path)='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered
    from public.question_threads t where t.id=p_thread_id for update;
  if not found then raise exception 'THREAD_NOT_FOUND'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;
  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception 'NOT_ROOM_PARTY'; end if;
  if v_thread_status in ('confirmed','closed','archived') then raise exception 'THREAD_LOCKED'; end if;
  if p_storage_path not like (v_room::text || '/' || p_thread_id::text || '/%') then raise exception 'STORAGE_PATH_MISMATCH'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id='question-room-attachments' and o.name = btrim(p_storage_path) and o.owner_id = v_uid::text) then raise exception 'STORAGE_OBJECT_NOT_OWNED'; end if;
  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception 'MESSAGE_THREAD_MISMATCH'; end if;
  if not v_is_mentor then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active' for update;
    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception 'SUBSCRIPTION_REFUND_PENDING'; end if;
  end if;

  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)
  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
    select coalesce(nullif(btrim(full_name),''), nullif(btrim(nickname),''), '멘토') into v_mentor_name from public.users where id=v_mentor;
    perform public.record_domain_notification(v_student, 'question_answered:'||p_thread_id::text, 'question_answered:'||p_thread_id::text,
      'question_answered','새 답변이 도착했어요', coalesce(v_mentor_name,'멘토')||'님이 파일을 보냈습니다.',
      '/question-room/'||v_room::text||'?thread='||p_thread_id::text,
      jsonb_build_object('room_id',v_room,'thread_id',p_thread_id), jsonb_build_object('room_id',v_room,'thread_id',p_thread_id));
  end if;
  return jsonb_build_object('ok',true,'attachment_id',v_att_id,'answered_transition',v_transitioned);
end; $$;

revoke all on function public.qna_create_question_thread(uuid,text,text,text,text) from public, anon;
revoke all on function public.qna_append_message(uuid,text) from public, anon;
revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon;
grant execute on function public.qna_create_question_thread(uuid,text,text,text,text) to authenticated, service_role;
grant execute on function public.qna_append_message(uuid,text) to authenticated, service_role;
grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role;

commit;

-- §V(rollback-only): 활성구독+pending 환불(subscription_prorated/mentor_suspended) → 생성·학생append·
--   학생첨부 SUBSCRIPTION_REFUND_PENDING 거부 · 환불 없으면 정상 · 무료 스레드 미적용 · 멘토 답변 무영향.

-- >>> NATIVE_BASELINE_PART 0150 | supabase/sql/143_p1_13_state_machine_hardening.sql | 143_p1_13_state_machine_hardening.sql <<<
-- 143_p1_13_state_machine_hardening.sql
-- P1-13 상태기계 완전성 감사 보정 — 131 을 수정하지 않고 confirm_subscription_checkout 재정의.
--
-- 추가/강화:
--  * 동시 생성 봉쇄: student·mentor pair advisory transaction lock(빈 pair 에도 잠금) + uq_subscriptions_pair
--    UNIQUE + ON CONFLICT 원자 upsert(SELECT FOR UPDATE 만으로 부족한 신규 pair 경쟁 봉쇄).
--  * 필수 게이트 추가: 학생 계정 활성 · 멘토 승인 · 멘토 cap(신규/재활성 시) · payment 종류(비구독 kind 거부) ·
--    payment mentor 존재 · plan_id 일치 · plan active · 정본 플랜 금액 · pending TTL · processing/종료 거부.
--  * 성공·원장 전필드 멱등: 재호출은 payment/subscription/ledger(user_id·ref_type·ref_id=subscription_id·
--    delta_cents=-amount·reason·idempotency_key)가 모두 일치할 때만 성공. succeeded 인데 구독/원장 불일치면
--    성공 반환하지 않고 구조화 실패로 격리(같은 트랜잭션 롤백 — 부분 커밋 없음).
-- 선행: 131·019/023·067.

create or replace function public.confirm_subscription_checkout(
  p_payment_id uuid, p_plan_id uuid, p_idempotency_key text default null
) returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;
  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;
  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;
  v_status text; v_suspended_until timestamptz;
  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;
  v_succeeded_aliases text[] := array['succeeded','paid','success','complete','captured'];
begin
  -- 결제 잠금 + 로드.
  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind
    from public.payments where id = p_payment_id for update;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if v_student is null then raise exception 'PAYMENT_NO_USER'; end if;
  if v_mentor is null then raise exception 'PAYMENT_NO_MENTOR'; end if;
  if lower(coalesce(v_kind,'')) in ('cash_topup','topup','cash','individual_question','iq','custom_order','custom_request','deliverable') then
    raise exception 'PAYMENT_KIND_INVALID';
  end if;

  -- 동시 생성 봉쇄: pair advisory xact lock(빈 pair 포함 전 구간 직렬화).
  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));

  -- 플랜 잠금 + 정본 금액.
  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents
    from public.mentor_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if v_plan_mentor <> v_mentor then raise exception 'PLAN_MENTOR_MISMATCH'; end if;
  if v_amount_cents is null or v_amount_cents <= 0 then raise exception 'PLAN_AMOUNT_INVALID'; end if;

  -- 이미 성공(별칭) → 전필드 멱등 검증 후 반환(불일치면 격리).
  if v_pay_status = any(v_succeeded_aliases) then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;
    if v_sub_id is null then raise exception 'ISOLATION_SUCCEEDED_NO_SUBSCRIPTION payment=%', p_payment_id; end if;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is null then raise exception 'ISOLATION_SUCCEEDED_NO_LEDGER payment=%', p_payment_id; end if;
    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'') <> 'subscriptions'
       or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents then
      raise exception 'ISOLATION_LEDGER_FIELD_MISMATCH payment=% sub=%', p_payment_id, v_sub_id;
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_sub_id,'payment_status','succeeded');
  end if;

  if v_pay_status = 'processing' then raise exception 'PAYMENT_PROCESSING'; end if;
  if v_pay_status in ('failed','canceled','refunded') then raise exception 'PAYMENT_NOT_PENDING'; end if;
  if v_pay_status <> 'pending' then raise exception 'PAYMENT_STATE_UNEXPECTED'; end if;
  if v_created_at is null or now() > v_created_at + interval '30 minutes' then raise exception 'PAYMENT_STALE'; end if;

  -- 학생 계정 활성.
  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' and (v_suspended_until is null or v_suspended_until > now()) then
    raise exception 'ACCOUNT_SUSPENDED';
  end if;

  -- 멘토 잠금 + 구독 open + 승인 + 플랜 active.
  perform 1 from public.mentor_profiles where user_id = v_mentor for update;
  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;
  if not coalesce(v_is_open, true) then raise exception 'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if not coalesce(v_plan_active, true) then raise exception 'PLAN_INACTIVE'; end if;

  -- 멘토 cap: 이 pair 가 현재 active 가 아닐 때(신규/재활성)만 가중치 추가 검사.
  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active') then
    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then
      raise exception 'MENTOR_CAP_EXCEEDED';
    end if;
  end if;

  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);

  -- 구독 생성/재활성화(UNIQUE + ON CONFLICT 원자).
  insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,
    started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)
  values (v_student, v_mentor, p_plan_id, v_plan_tier, 'active', p_payment_id,
    now(), now(), now()+interval '1 month', now()+interval '1 month', 'monthly', false, p_payment_id)
  on conflict (student_id, mentor_id) do update set
    plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status='active', payment_id=excluded.payment_id,
    last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),
    current_period_start=now(), current_period_end=now()+interval '1 month', next_billing_at=now()+interval '1 month',
    cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,
    last_renewed_at=now(), updated_at=now()
  returning id into v_sub_id;

  -- 기존 원장 행이 있으면 전필드 일치만 허용(불일치 격리).
  select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
    from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
  if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id
     or coalesce(v_l_reftype,'') <> 'subscriptions' or coalesce(v_l_reason,'') <> 'subscription_payment'
     or v_l_delta <> -v_amount_cents) then
    raise exception 'ISOLATION_LEDGER_FIELD_MISMATCH payment=% sub=%', p_payment_id, v_sub_id;
  end if;

  perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);

  update public.payments set status='succeeded', plan_id=p_plan_id,
    metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('planId',p_plan_id::text,'subscription_id',v_sub_id::text),
    updated_at=now() where id=p_payment_id;

  return jsonb_build_object('ok',true,'subscription_id',v_sub_id,'payment_status','succeeded','amount_cents',v_amount_cents,'reactivated',v_reactivated);
end;
$$;

revoke all on function public.confirm_subscription_checkout(uuid,uuid,text) from public, anon, authenticated;
grant execute on function public.confirm_subscription_checkout(uuid,uuid,text) to service_role;

-- §V(rollback-only): 게이트 각각 거부(정지학생·미승인멘토·cap초과·비구독kind·plan불일치/미가격·TTL·processing) ·
--   pending→active+debit+succeeded · 재호출 전필드 멱등 · succeeded인데 ledger 불일치 격리(부분커밋 없음) ·
--   동시 신규 pair 이중 구독 없음(UNIQUE+advisory). 독립 2세션 실측 = CONCURRENCY_VALIDATION_DEBT.

-- >>> NATIVE_BASELINE_PART 0151 | supabase/sql/144_p1_8a_direct_write_eligibility.sql | 144_p1_8a_direct_write_eligibility.sql <<<
-- 144_p1_8a_direct_write_eligibility.sql
-- P1-8A 반려 보정 (1-1/1-2/1-3) — 141/142 미수정, 가드 함수 재정의(신규 파일).
--
-- 1-1 직접 thread 생성 한도 우회: 직접 question_threads INSERT 에서 전 자격을 BEFORE 가드가 강제하고,
--     무료 경로는 AFTER 트리거가 free_question_usage(thread_id 링크)를 원자 소비한다. 구버전의 별도
--     usage INSERT(thread_id NULL, 직접)는 안전한 멱등 no-op(시간 근접 휴리스틱 없음).
-- 1-2 직접 멘토 answered: 콘텐츠 없이 status만 answered 로 바꾸는 직접 UPDATE 거부(DIRECT_ANSWERED_VIA_CONTENT_ONLY).
--     멘토 첫 실제 메시지/첨부는 AFTER 트리거가 self-gating 헬퍼(멘토 본인 + 실제 멘토 콘텐츠 존재 확인)를
--     호출해 pending/open→answered + canonical question_answered exactly-once 처리(0회 발송 아님).
-- 1-3 업로드 자격: qra_uploader_allowed_for_path 에 양방향 차단 추가(계정·멘토는 141). 활성구독/무료 자격·
--     pending refund 는 등록 RPC(qna_register_attachment)가 정본 기록으로 강제(업로드 객체는 등록 전 inert,
--     실패 시 보상 삭제) — 층위 방어.
-- 판별: qna_* RPC(owner=postgres)=current_user 'postgres', 직접='authenticated'. 가드/AFTER 트리거는 INVOKER,
--     answered 전이 헬퍼는 self-gating DEFINER(내부 UPDATE 는 postgres 컨텍스트라 qt 가드 skip).
-- 선행: 136/139/141/142.

begin;
set local lock_timeout='5s';

-- 멘토 첫 콘텐츠 → answered 전이 + exactly-once 알림. self-gating: 호출자=room 멘토 AND 실제 멘토 콘텐츠 존재.
create or replace function public.qna_apply_answered_transition(p_thread_id uuid)
returns void language plpgsql security definer set search_path to 'public' as $$
declare v_room uuid; v_status text; v_first timestamptz; v_student uuid; v_mentor uuid; v_updated int; v_name text;
begin
  select mentor_student_room_id, status, first_answered_at into v_room, v_status, v_first from public.question_threads where id=p_thread_id;
  if v_room is null then return; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;
  if auth.uid() is distinct from v_mentor then return; end if;
  if v_first is not null or v_status not in ('pending','open') then return; end if;
  if not exists (select 1 from public.question_messages m where m.thread_id=p_thread_id and m.author_id=v_mentor)
     and not exists (select 1 from public.question_attachments a where a.thread_id=p_thread_id and a.author_id=v_mentor) then
    return; -- content-less: no-op
  end if;
  update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
  get diagnostics v_updated = row_count;
  if v_updated>0 then
    select coalesce(nullif(btrim(full_name),''),nullif(btrim(nickname),''),'멘토') into v_name from public.users where id=v_mentor;
    perform public.record_domain_notification(v_student,'question_answered:'||p_thread_id::text,'question_answered:'||p_thread_id::text,
      'question_answered','새 답변이 도착했어요',coalesce(v_name,'멘토')||'님이 답변을 남겼습니다.',
      '/question-room/'||v_room::text||'?thread='||p_thread_id::text,
      jsonb_build_object('room_id',v_room,'thread_id',p_thread_id),jsonb_build_object('room_id',v_room,'thread_id',p_thread_id));
  end if;
end; $$;
revoke all on function public.qna_apply_answered_transition(uuid) from public, anon;
grant execute on function public.qna_apply_answered_transition(uuid) to authenticated, service_role;

-- 양방향 차단 검사(DEFINER: INVOKER 트리거가 RLS 로 상대의 차단 행을 못 보는 문제 방지).
create or replace function public.qna_users_blocked(p_a uuid, p_b uuid)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (select 1 from public.user_blocks where (blocker_id=p_a and blocked_id=p_b) or (blocker_id=p_b and blocked_id=p_a));
$$;
revoke all on function public.qna_users_blocked(uuid,uuid) from public, anon;
grant execute on function public.qna_users_blocked(uuid,uuid) to authenticated, service_role;

-- 1-1: 직접 thread INSERT 전 자격 강제. UPDATE 는 직접 answered/first_answered 거부.
create or replace function public.qt_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare
  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;
  v_created_at timestamptz; v_total int; v_per int; v_has_sub boolean; v_usage json; v_sub_id uuid;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;
  if TG_OP = 'INSERT' then
    if v_student is null then raise exception 'ROOM_NOT_FOUND'; end if;
    if v_uid is distinct from v_student then raise exception 'DIRECT_CREATE_STUDENT_ONLY'; end if;
    if coalesce(NEW.status,'pending') not in ('pending','open') then raise exception 'DIRECT_INSERT_STATUS_FORBIDDEN'; end if;
    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception 'DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN'; end if;
    select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;
    if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
    if lower(coalesce(v_status,'active'))='suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
    if public.qna_users_blocked(v_student, v_mentor) then raise exception 'BLOCKED'; end if;
    if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
    v_has_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active');
    if v_has_sub then
      select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active';
      if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception 'SUBSCRIPTION_REFUND_PENDING'; end if;
      v_usage := public.get_weekly_question_usage(v_student, v_mentor);
      if not coalesce((v_usage->>'can_ask')::boolean, false) then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    else
      if v_created_at is not null and now() >= v_created_at + interval '7 days' then raise exception 'FREE_QUOTA_EXPIRED'; end if;
      select count(*) into v_total from public.free_question_usage where student_id=v_student;
      if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
      select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;
      if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    end if;
    return NEW;
  end if;
  if NEW.status is distinct from OLD.status then
    if NEW.status = 'answered' then raise exception 'DIRECT_ANSWERED_VIA_CONTENT_ONLY'; end if;
    if NEW.status = 'confirmed' and v_uid is distinct from v_student then raise exception 'DIRECT_CONFIRM_STUDENT_ONLY'; end if;
  end if;
  if NEW.first_answered_at is distinct from OLD.first_answered_at then raise exception 'DIRECT_FIRST_ANSWERED_VIA_CONTENT_ONLY'; end if;
  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status) and v_uid is distinct from v_student then raise exception 'DIRECT_WRONG_FLAG_STUDENT_ONLY'; end if;
  return NEW;
end; $$;

-- 1-1: 직접 무료 thread 생성 후(AFTER, thread FK 존재) 무료 usage 원자 소비.
create or replace function public.qt_direct_consume_free_usage()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_student uuid; v_mentor uuid;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;
  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active') then
    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, NEW.id);
  end if;
  return NEW;
end; $$;
drop trigger if exists trg_qt_direct_consume_free_usage on public.question_threads;
create trigger trg_qt_direct_consume_free_usage after insert on public.question_threads for each row execute function public.qt_direct_consume_free_usage();

-- 1-1: 구버전 별도 usage INSERT(thread_id NULL, 직접) 안전 멱등 no-op(AFTER 트리거가 정본 소비).
create or replace function public.fqu_legacy_standalone_noop()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
begin
  if public.qna_is_direct_untrusted_writer() and NEW.thread_id is null then return null; end if;
  return NEW;
end; $$;
drop trigger if exists trg_fqu_legacy_standalone_noop on public.free_question_usage;
create trigger trg_fqu_legacy_standalone_noop before insert on public.free_question_usage for each row execute function public.fqu_legacy_standalone_noop();

-- 1-2/1-3 BEFORE 가드: 종료 스레드·경로·owner 위조 거부(answered 전이는 AFTER 에서).
create or replace function public.qm_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select status into v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_MSG_THREAD_LOCKED'; end if;
  return NEW;
end; $$;

create or replace function public.qa_direct_write_guard()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
declare v_room uuid; v_status text;
begin
  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;
  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;
  if v_status in ('confirmed','closed','archived') then raise exception 'DIRECT_ATT_THREAD_LOCKED'; end if;
  if NEW.storage_path is null or NEW.storage_path not like (v_room::text||'/'||NEW.thread_id::text||'/%') then raise exception 'DIRECT_ATT_PATH_FORGERY'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id='question-room-attachments' and o.name=NEW.storage_path and o.owner_id=auth.uid()::text) then raise exception 'DIRECT_ATT_OBJECT_NOT_OWNED'; end if;
  return NEW;
end; $$;

-- 1-2 AFTER: 직접 멘토 첫 메시지/첨부 → self-gating answered 전이.
create or replace function public.qm_direct_answered_after()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
begin
  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;
  return NEW;
end; $$;
drop trigger if exists trg_qm_direct_answered_after on public.question_messages;
create trigger trg_qm_direct_answered_after after insert on public.question_messages for each row execute function public.qm_direct_answered_after();

create or replace function public.qa_direct_answered_after()
returns trigger language plpgsql security invoker set search_path to 'public' as $$
begin
  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;
  return NEW;
end; $$;
drop trigger if exists trg_qa_direct_answered_after on public.question_attachments;
create trigger trg_qa_direct_answered_after after insert on public.question_attachments for each row execute function public.qa_direct_answered_after();

-- 1-3: 업로드 자격 helper 에 양방향 차단 추가(계정·멘토는 141).
create or replace function public.qra_uploader_allowed_for_path(p_name text)
returns boolean language plpgsql stable security definer set search_path to 'public' as $$
declare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;
begin
  if v_uid is null then return false; end if;
  v_room := public.qra_room_uuid_from_path(p_name);
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;
  if v_student is null then return false; end if;
  select status into v_status from public.users where id = v_uid;
  if lower(coalesce(v_status,'active')) = 'banned' then return false; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' then
    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;
  end if;
  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;
  if public.qna_users_blocked(v_student, v_mentor) then return false; end if;
  return true;
end; $$;

commit;

-- §V(rollback-only, PASS): 직접 thread-only 생성이 무료 usage 원자 소비(4번째 멘토별 거부)·구버전 standalone
--   usage no-op·직접 status-only answered 거부·멘토 첫 메시지 answered+exactly-once·RPC(postgres) 무영향.

-- >>> NATIVE_BASELINE_PART 0152 | supabase/sql/145_p1_13_anomaly_persistence.sql | 145_p1_13_anomaly_persistence.sql <<<
-- 145_p1_13_anomaly_persistence.sql
-- P1-13 (1-5) 금융 불일치 anomaly 영속성. 131/143 미수정, confirm_subscription_checkout 재정의.
--
-- 문제: 143 은 원장/구독 불일치 시 RAISE → audit 기록까지 롤백. 영속 기록이 남지 않는다.
-- 해결:
--   * service-role 전용 anomaly 테이블(RLS deny + revoke).
--   * 금융 write 전 사전 불일치는 anomaly INSERT 후 {ok:false,code} 반환(금융 변경 0 → anomaly 만 커밋).
--   * 금융 write 도중 오류는 내부 subtransaction(BEGIN..EXCEPTION)으로 구독·차감·payment 변경을 롤백한 뒤
--     바깥에서 anomaly 를 기록하고 {ok:false} 반환(anomaly 만 커밋).
-- 반환 계약 변경: 이제 anomaly 는 RAISE 가 아니라 {ok:false,code,anomaly_id} 로 반환한다. 웹은 data.ok 를 검사.
-- 선행: 131·143·019/023·067.

begin;
set local lock_timeout='5s';

create table if not exists public.subscription_checkout_anomalies (
  id uuid primary key default gen_random_uuid(),
  payment_id uuid,
  subscription_id uuid,
  code text not null,
  detail text,
  expected jsonb,
  found jsonb,
  created_at timestamptz not null default now()
);
alter table public.subscription_checkout_anomalies enable row level security;
-- 정책 미부여 → authenticated/anon 접근 불가. service_role 은 RLS bypass. DEFINER(postgres) INSERT 가능.
revoke all on table public.subscription_checkout_anomalies from public, anon, authenticated;
grant select, insert on table public.subscription_checkout_anomalies to service_role;

create or replace function public.confirm_subscription_checkout(
  p_payment_id uuid, p_plan_id uuid, p_idempotency_key text default null
) returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;
  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;
  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;
  v_status text; v_suspended_until timestamptz;
  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;
  v_succeeded_aliases text[] := array['succeeded','paid','success','complete','captured'];
  v_anom uuid; v_err text; v_errcode text;
begin
  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind
    from public.payments where id = p_payment_id for update;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if v_student is null then raise exception 'PAYMENT_NO_USER'; end if;
  if v_mentor is null then raise exception 'PAYMENT_NO_MENTOR'; end if;
  if lower(coalesce(v_kind,'')) in ('cash_topup','topup','cash','individual_question','iq','custom_order','custom_request','deliverable') then raise exception 'PAYMENT_KIND_INVALID'; end if;

  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));

  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents
    from public.mentor_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if v_plan_mentor <> v_mentor then raise exception 'PLAN_MENTOR_MISMATCH'; end if;
  if v_amount_cents is null or v_amount_cents <= 0 then raise exception 'PLAN_AMOUNT_INVALID'; end if;

  -- 이미 성공 → 전필드 멱등 검증. 불일치는 anomaly INSERT 후 {ok:false} (금융 변경 없음).
  if v_pay_status = any(v_succeeded_aliases) then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;
    if v_sub_id is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, null, 'SUCCEEDED_NO_SUBSCRIPTION', 'succeeded payment without subscription') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_SUBSCRIPTION','anomaly_id',v_anom);
    end if;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, v_sub_id, 'SUCCEEDED_NO_LEDGER', 'succeeded payment without ledger debit') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_LEDGER','anomaly_id',v_anom);
    end if;
    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'') <> 'subscriptions'
       or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        values (p_payment_id, v_sub_id, 'LEDGER_FIELD_MISMATCH', 'idempotent re-check field mismatch',
          jsonb_build_object('user_id',v_student,'ref_id',v_sub_id,'ref_type','subscriptions','reason','subscription_payment','delta_cents',-v_amount_cents),
          jsonb_build_object('user_id',v_l_user,'ref_id',v_l_refid,'ref_type',v_l_reftype,'reason',v_l_reason,'delta_cents',v_l_delta))
        returning id into v_anom;
      return jsonb_build_object('ok',false,'code','LEDGER_FIELD_MISMATCH','anomaly_id',v_anom);
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_sub_id,'payment_status','succeeded');
  end if;

  if v_pay_status = 'processing' then raise exception 'PAYMENT_PROCESSING'; end if;
  if v_pay_status in ('failed','canceled','refunded') then raise exception 'PAYMENT_NOT_PENDING'; end if;
  if v_pay_status <> 'pending' then raise exception 'PAYMENT_STATE_UNEXPECTED'; end if;
  if v_created_at is null or now() > v_created_at + interval '30 minutes' then raise exception 'PAYMENT_STALE'; end if;

  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;

  perform 1 from public.mentor_profiles where user_id = v_mentor for update;
  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;
  if not coalesce(v_is_open, true) then raise exception 'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if not coalesce(v_plan_active, true) then raise exception 'PLAN_INACTIVE'; end if;

  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''))='active') then
    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception 'MENTOR_CAP_EXCEEDED'; end if;
  end if;

  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);

  -- 금융 write subtransaction: 오류 시 구독·차감·payment 변경 롤백, 바깥에서 anomaly 기록.
  begin
    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,
      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)
    values (v_student, v_mentor, p_plan_id, v_plan_tier, 'active', p_payment_id,
      now(), now(), now()+interval '1 month', now()+interval '1 month', 'monthly', false, p_payment_id)
    on conflict (student_id, mentor_id) do update set
      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status='active', payment_id=excluded.payment_id,
      last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),
      current_period_start=now(), current_period_end=now()+interval '1 month', next_billing_at=now()+interval '1 month',
      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,
      last_renewed_at=now(), updated_at=now()
    returning id into v_sub_id;

    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id
       or coalesce(v_l_reftype,'') <> 'subscriptions' or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents) then
      raise exception 'LEDGER_FIELD_MISMATCH';
    end if;

    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);
    update public.payments set status='succeeded', plan_id=p_plan_id,
      metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('planId',p_plan_id::text,'subscription_id',v_sub_id::text),
      updated_at=now() where id=p_payment_id;
  exception when others then
    get stacked diagnostics v_errcode = returned_sqlstate;
    v_err := sqlerrm;
  end;

  if v_err is not null then
    -- 잔액 부족은 정상 사용자 오류(anomaly 아님) → anomaly 미기록.
    if v_err like '%CASH_INSUFFICIENT%' then
      return jsonb_build_object('ok',false,'code','CASH_INSUFFICIENT');
    end if;
    -- 그 외(원장 불일치·예상 밖) 금융 변경은 subtransaction 롤백됨. anomaly 만 기록·커밋.
    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      values (p_payment_id, v_sub_id,
        case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end,
        left(v_err, 500)) returning id into v_anom;
    return jsonb_build_object('ok',false,
      'code', case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end,
      'sqlstate',v_errcode,'anomaly_id',v_anom);
  end if;

  return jsonb_build_object('ok',true,'subscription_id',v_sub_id,'payment_status','succeeded','amount_cents',v_amount_cents,'reactivated',v_reactivated);
end;
$$;
revoke all on function public.confirm_subscription_checkout(uuid,uuid,text) from public, anon, authenticated;
grant execute on function public.confirm_subscription_checkout(uuid,uuid,text) to service_role;

commit;

-- §V(rollback-only): anomaly 는 별도 트랜잭션에서 조회 가능(영속) · 불일치 시 구독/원장/payment 변경 0 ·
